from pathlib import Path
import json,statistics,random,hashlib,platform
from collections import Counter
r=json.loads(Path('research/results/continuation.json').read_text());rows=r['games']
def quant(xs,p):return sorted(xs)[max(0,__import__('math').ceil(len(xs)*p)-1)]
def ci(clusters):
 rng=random.Random(112);means=[statistics.mean(rng.choices(clusters,k=len(clusters))) for _ in range(5000)]
 return f'{quant(means,.025):.3f}–{quant(means,.975):.3f}'
s=['# Continuation experimental results','', '**Experimentally supported:** observed behavior under the named weak research agents, not human depth or optimal fairness. **Verified:** stated command completed and result records exist.', '', f"{len(rows)} new games, seven configurations, eight independent seed clusters per configuration. Runtime {r['seconds']:.2f} s; {r['python']}, {r['platform']}. Concurrent synthetic population work can affect elapsed times. No Windows/iPhone runtime was used.", '', '## Protocol', '', 'Per configuration and seed 0–7: one random/random game, color-swapped greedy/random, tactical/greedy and deep/tactical pairs (7 games per seed, 56 per configuration). No duplicate random/random color swaps. Different protocols sharing a seed are clustered together in uncertainty estimates. The same seeds across configurations are matched random streams but trajectories diverge. Record all moves, not only openings. All agents use the SAME evaluator and terminal handling. Greedy depth cap 1, tactical 2, deep 4; iterative deepening commits only a fully completed root iteration. Each turn has hard 800-node cap including prior iterations; actual nodes and deepest completed iteration are retained. Uncompleted deeper searches are discarded; deeper cap is not evidence of reaching that depth. No quiescence, learned evaluation or transposition table.', '', 'Intervals: percentile bootstrap of 8 seed clusters, 5,000 resamples with seed 112. Small cluster count makes these exploratory intervals unstable. All-win/all-draw clusters yield degenerate intervals; that is not zero true uncertainty. First-player score includes 0.5 per draw and pools these protocols; it measures this experiment, not game-theoretic advantage. Agent score is measured across both colors within each seed. Seeds are not humans or an independent evaluator. Do not use these intervals to certify fairness.', '', '|Config|First / draw / second|First score [cluster 95%]|Plies p50 / p90|Mean branch|End reasons|Distinct first / four-ply openings|', '|---|---|---|---|---|---|---|']
for config in r['configs']:
 name=config['name'];a=[x for x in rows if x['config']==name];c=Counter(x['winner'] for x in a);clusters=[statistics.mean((x['winner']+1)/2 for x in a if x['seed']==seed) for seed in range(8)]
 s.append(f"|{name}|{c[1]} / {c[0]} / {c[-1]}|{statistics.mean(clusters):.3f} [{ci(clusters)}]|{statistics.median(x['plies'] for x in a):g} / {quant([x['plies'] for x in a],.9)}|{statistics.mean(v for x in a for v in x['branches']):.1f}|{dict(Counter(x['reason'] for x in a))}|{len({tuple(x['trace'][0]) for x in a})} / {len({str(x['trace'][:4]) for x in a})}|")
s+=['', '## Strength and completed search depth', '', '|Config|Pair|Stronger W/D/L|Stronger score [paired 95%]|', '|---|---|---|---|']
for config in r['configs']:
 for strong,weak in [('greedy','random'),('tactical','greedy'),('deep','tactical')]:
  a=[x for x in rows if x['config']==config['name'] and set(x['agents'])=={strong,weak}];c=Counter(x['winner']*(1 if x['agents'][0]==strong else -1) for x in a)
  cluster=[statistics.mean((x['winner']*(1 if x['agents'][0]==strong else -1)+1)/2 for x in a if x['seed']==seed) for seed in range(8)]
  s.append(f"|{config['name']}|{strong}/{weak}|{c[1]}/{c[0]}/{c[-1]}|{statistics.mean(cluster):.3f} [{ci(cluster)}]|")
s+=['', '|Config|Deep agent completed depth counts|Move time p50 / p95 ms (all agents)|Disconnected side-positions / total side-positions|', '|---|---|---|---|']
for config in r['configs']:
 a=[x for x in rows if x['config']==config['name']];ds=Counter(d for x in a for i,d in enumerate(x['depths']) if x['agents'][i%2]=='deep');times=[t*1000 for x in a for t in x['seconds']]
 s.append(f"|{config['name']}|{dict(sorted(ds.items()))}|{statistics.median(times):.2f} / {quant(times,.95):.2f}|{sum(x['stranded_side_positions'] for x in a)} / {sum(x['plies']*2 for x in a)}|")
s+=['', '## Interpretation boundaries', '', 'No opening is proven dominant. Distinct action sequences do not establish strategic variety. No comeback cohort, human readability metric, calibrated rating ladder or subjective qualitative strategy change was measured. Agent comparisons can expose horizon sensitivity but cannot show exceptional depth. Node cap and evaluator may favor one configuration. The terminal limit is 120 instead of historical 100 and all continuation variants remove v0.1 empty-move connectivity, so compare mechanics to free5 within this run. Size comparisons also alter reserves. Population benchmark and forecast experiment are in world_bench.json.', '', '**Verified by rule argument:** with only two anchors on board and empty reserves, every variant here has no route to capture: both powers are one, breach forbids anchors, relay lacks a friendly jumping piece, pressure pushes but never ejects. Thus all such endgames draw under the bound. This is a genuine strategic limitation, not repaired by the new mechanics. Reduced opening states were not solved. Next: anchor-pressure victory or targeted anchor vulnerability must be formally compared against network identity and teaching burden.', '', '## Reproduction', '', 'From repository root: `python research/experiments/continuation.py`, `python research/experiments/world_bench.py`, `python research/experiments/continuation_report.py`, `python -m unittest discover -s research/experiments -v`. No dependencies outside Python 3.12 standard library. Baseline sources/results are preserved unchanged. Timing varies; game traces are deterministic for these scripts and budgets.']
Path('research/19_CONTINUATION_RESULTS.md').write_text('\n'.join(s)+'\n')
files=['research/experiments/continuation.py','research/experiments/test_continuation.py','research/experiments/world_bench.py','research/experiments/continuation_report.py','research/results/continuation.json','research/results/world_bench.json','research/results/platform_sources.json','research/experiments/audit_continuation.py','research/experiments/check_docs.py','research/results/continuation_audit.json','research/results/continuation_tests.txt']
Path('research/results/continuation_manifest.json').write_text(json.dumps(dict(python=platform.python_version(),commands=['python research/experiments/continuation.py','python research/experiments/world_bench.py','python research/experiments/continuation_report.py'],sha256={f:hashlib.sha256(Path(f).read_bytes()).hexdigest() for f in files}),indent=2)+'\n')
print('\n'.join(s[:24]))
